function resolveJournal_0Writes(seam: ISqlSeam, before: Snapshot, arrivals: IArrivalBatch): Observable<readonly SqlStatement[]> {
  const trigger_rows = trigger_occurrences("log", "ping", before.ping, arrivals);
  if (trigger_rows.length === 0) return of([]);
  return forkJoin(trigger_rows.map((arrival) => seam.runner.execute(seam.db, { sql: EDGE_JOURNAL_0_PROJECT_SQL, args: bind_args(arrival.row) }))).pipe(
    map((results) => {
      const written: SqlStatement[] = [];
      for (const result of results) {
        const projected_rows = result.rows.map((row) => EDGE_JOURNAL_0_HEAD_COLUMNS.map((column) => row[column] as IRowValue) as IRow);
        for (const projected_row of projected_rows) {
          written.push({ sql: EDGE_JOURNAL_0_WRITE_SQL, args: bind_args(projected_row) });
        }
      }
      return written;
    }),
  );
}

